 q=pd.read_csv(R/(name+'_cluster_annotation_QA.csv'),dtype={'cluster':str});mixed=q.fraction_CD1C.ge(.3)&q.fraction_FCER1A.ge(.2)&q.fraction_C1QC.ge(.4);q.loc[mixed,'assigned_group']='Mixed_APC';q.to_csv(R/(name+'_cluster_annotation_QA.csv'),index=False)
 a=ad.read_h5ad(R/(name+'_harmonized_counts_QC.h5ad'));a.obs['harmonized_group']=a.obs.harmonized_group.astype(str);a.obs['fine_group']=a.obs.fine_group.astype(str);sel=a.obs.myeloid_cluster.astype(str).isin(q.loc[mixed,'cluster']);a.obs.loc[sel,'harmonized_group']='Mixed_APC';a.obs.loc[sel,'fine_group']='Mixed_APC';a.obs.to_csv(R/(name+'_harmonized_cell_metadata.csv.gz'));a.write_h5ad(R/(name+'_harmonized_counts_QC.h5ad'),compression='gzip');a.obs.groupby(['donor_id','original_group','harmonized_group','fine_group'],observed=True).size().rename('cells').reset_index().to_csv(R/(name+'_annotation_transitions.csv'),index=False)
 s=json.loads((R/(name+'_annotation_summary.json')).read_text());s['groups']=a.obs.harmonized_group.value_counts().to_dict();s['target_positive_cells']=int(a.obs.fine_group.eq('TAM_PGAM5_detected').sum());s['target_undetected_cells']=int(a.obs.fine_group.isin(['TAM_PGAM5_undetected','Cycling_TAM_PGAM5_undetected']).sum());s['mixed_APC_rule_revision']='Before joint reference training; same rule used in all datasets, externally inspected for label sanity; not blinded annotation';(R/(name+'_annotation_summary.json')).write_text(json.dumps(s,indent=2));print(name,s['groups'],s['target_positive_cells'],flush=True)
